 peach yz-plane (figure x=0)  → PlaneGeometry(6,6) no rot,     MeshBasicMaterial #F8C4A2 op .55, depthWrite:false
 blue xz-plane (figure y=0)   → PlaneGeometry(6,6) rotY  90°,  MeshBasicMaterial #9A9AC8 op .55, depthWrite:false
 plane borders                → EdgesGeometry + LineSegments in darker tint (#4E9A93 / #E08A5A / #6B6BA8)
 positive axes (x,y,z)        → CylinderGeometry(0.02,0.02,3.35) black, depthTest:false
 arrowheads                   → ConeGeometry(0.1,0.3,18) black at +3.45
 negative axes                → Line + LineDashedMaterial #8A8A8A, 0 → -3.3
 origin                       → SphereGeometry(0.07) black
 octant pick/highlight wedges → 8 × BoxGeometry(2.9) centred at (±1.5,±1.5,±1.5), opacity 0 → 0.35 gold
 axis letters x,y,z           → addLabel bold italic 15px
 octant sign triples + 'I'    → addLabel 13px (I bold 15px)
──────────────────────────────────────────────────────────────────────────── */

// figure coords (x = toward viewer, y = right, z = up)  →  world (y-up)
const F = (fx, fy, fz) => new THREE.Vector3(fy, fz, fx);

/* ── translucent coordinate planes ───────────────────────────────────────── */
function makePlane(fill, edge, opacity, rot, order) {
  const geo = new THREE.PlaneGeometry(6, 6);
  const mat = new THREE.MeshBasicMaterial({
    color: fill, transparent: true, opacity,
    depthWrite: false, side: THREE.DoubleSide
  });
  const mesh = new THREE.Mesh(geo, mat);
  rot(mesh);
  mesh.renderOrder = order;
  scene.add(mesh);
  const line = new THREE.LineSegments(
    new THREE.EdgesGeometry(geo),
    new THREE.LineBasicMaterial({ color: edge, transparent: true, opacity: 0.95, depthWrite: false })
  );
  line.renderOrder = order + 4;
  mesh.add(line);
  return { mesh, mat, line, base: opacity };
}

const planeXY = makePlane(0xA9D2CE, 0x4E9A93, 0.45, m => { m.rotation.x = -Math.PI / 2; }, 1);
const planeXZ = makePlane(0x9A9AC8, 0x6B6BA8, 0.55, m => { m.rotation.y = Math.PI / 2; }, 2);
const planeYZ = makePlane(0xF8C4A2, 0xE08A5A, 0.55, m => { }, 3);

planeXY.mat.userData = { target: 0.45 };
planeXZ.mat.userData = { target: 0.55 };
planeYZ.mat.userData = { target: 0.55 };

/* ── axes ────────────────────────────────────────────────────────────────── */
const blackMat = new THREE.MeshBasicMaterial({ color: 0x000000, depthTest: false });
const UP = new THREE.Vector3(0, 1, 0);

function solidAxis(dirFig) {
  const dir = F(dirFig[0], dirFig[1], dirFig[2]).normalize();
  const q = new THREE.Quaternion().setFromUnitVectors(UP, dir);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.02, 3.35, 12), blackMat);
  shaft.quaternion.copy(q);
  shaft.position.copy(dir).multiplyScalar(3.35 / 2);
  shaft.renderOrder = 12;
  scene.add(shaft);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.3, 18), blackMat);
  cone.quaternion.copy(q);
  cone.position.copy(dir).multiplyScalar(3.45);
  cone.renderOrder = 12;
  scene.add(cone);
}

function dashedAxis(dirFig) {
  const dir = F(dirFig[0], dirFig[1], dirFig[2]).normalize();
  const geo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, 0, 0), dir.clone().multiplyScalar(3.3)
  ]);
  const line = new THREE.Line(geo, new THREE.LineDashedMaterial({
    color: 0x8A8A8A, dashSize: 0.16, gapSize: 0.11, depthTest: false
  }));
  line.computeLineDistances();
  line.renderOrder = 11;
  scene.add(line);
}

solidAxis([1, 0, 0]);  solidAxis([0, 1, 0]);  solidAxis([0, 0, 1]);
dashedAxis([-1, 0, 0]); dashedAxis([0, -1, 0]); dashedAxis([0, 0, -1]);

const origin = new THREE.Mesh(new THREE.SphereGeometry(0.07, 16, 12), blackMat);
origin.renderOrder = 13;
scene.add(origin);

/* ── eight octant wedges (pick targets + highlight volumes) ──────────────── */
const OCT = [
  { s: [1, 1, 1],    p: [1.2, 1.2, 1.2],   t: '(+, +, +)' },
  { s: [-1, -1, 1],  p: [-1, -1, 3.4],     t: '(&minus;, &minus;, +)' },
  { s: [1, -1, 1],   p: [1.5, -2.6, 2.2],  t: '(+, &minus;, +)' },
  { s: [-1, 1, 1],   p: [-1.5, 2.6, 2.2],  t: '(&minus;, +, +)' },
  { s: [1, -1, -1],  p: [1.5, -2.6, -2.2], t: '(+, &minus;, &minus;)' },
  { s: [1, 1, -1],   p: [1.5, 1.0, -3.0],  t: '(+, +, &minus;)' },
  { s: [-1, 1, -1],  p: [-1.5, 2.8, -1.6], t: '(&minus;, +, &minus;)' },
  { s: [-1, -1, -1], p: [-1.35, -1.35, -1.35], t: '(&minus;, &minus;, &minus;)' }
];
const kOf = s => s.join(',');
const octBoxes = [];
const octMap = {};

OCT.forEach(o => {
  const mat = new THREE.MeshBasicMaterial({
    color: 0xE8B23A, transparent: true, opacity: 0,
    depthWrite: false, side: THREE.DoubleSide
  });
  const box = new THREE.Mesh(new THREE.BoxGeometry(2.9, 2.9, 2.9), mat);
  box.position.copy(F(o.s[0] * 1.5, o.s[1] * 1.5, o.s[2] * 1.5));
  box.renderOrder = 0;
  box.userData.key = kOf(o.s);
  mat.userData = { target: 0, baseColor: 0xE8B23A };
  scene.add(box);
  octBoxes.push(box);
  octMap[kOf(o.s)] = { def: o, box, mat, label: null };
  registerInteractive(box, {
    title: 'Octant ' + o.t.replace(/&minus;/g, '\u2212'),
    tooltip: o.t.replace(/&minus;/g, '\u2212'),
    body: 'This wedge lies on the ' + (o.s[0] > 0 ? 'positive' : 'negative') +
      ' side of the yz-plane (x = 0), the ' + (o.s[1] > 0 ? 'positive' : 'negative') +
      ' side of the xz-plane (y = 0), and the ' + (o.s[2] > 0 ? 'positive' : 'negative') +
      ' side of the xy-plane (z = 0) — so every point in it has coordinate signs ' +
      o.t.replace(/&minus;/g, '\u2212') + '.'
  });
});

/* ── camera (after all geometry) ─────────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.72
});
document.getElementById('btnReset').style.display = '';

/* ── labels ──────────────────────────────────────────────────────────────── */
const AX = { bold: true, fontSize: '15px', color: '#000' };
addLabel('<i>z</i>', F(0, 0, 3.6), { ...AX, offset: [-2, -16] });
addLabel('<i>y</i>', F(0, 3.6, 0), { ...AX, offset: [18, 6] });
addLabel('<i>x</i>', F(3.6, 0, 0), { ...AX, offset: [-8, 18] });

OCT.forEach(o => {
  const e = addLabel(o.t, F(o.p[0], o.p[1], o.p[2]),
    { fontSize: '13px', color: '#141428' });
  octMap[kOf(o.s)].label = e;
});
const labelI = addLabel('<b>I</b>', F(1.2, 1.2, 1.2),
  { fontSize: '16px', bold: true, color: '#141428', offset: [0, -20] });

/* ── hide the octant that is behind all three sheets ─────────────────────── */
function updateHidden() {
  const cf = [camera.position.z, camera.position.x, camera.position.y]; // -> figure x,y,z
  const hiddenKey = kOf([cf[0] > 0 ? -1 : 1, cf[1] > 0 ? -1 : 1, cf[2] > 0 ? -1 : 1]);
  for (const k in octMap) {
    const vis = (k === hiddenKey) ? 'hidden' : 'visible';
    octMap[k].label.div.style.visibility = vis;
    if (k === '1,1,1') labelI.div.style.visibility = vis;
  }
}
controls.addEventListener('change', updateHidden);
updateHidden();

/* ── plane emphasis + half-space tinting ─────────────────────────────────── */
const WARM = 0xE8834A, COOL = 0x4A7FE8, GOLD = 0xE8B23A;
let emphasis = 'none';
let hovered = null;

function refreshOctantMats() {
  OCT.forEach(o => {
    const rec = octMap[kOf(o.s)];
    let col = GOLD, op = 0;
    if (emphasis !== 'none') {
      const idx = emphasis === 'yz' ? 0 : emphasis === 'xz' ? 1 : 2;
      col = o.s[idx] > 0 ? WARM : COOL;
      op = 0.13;
    }
    if (hovered === kOf(o.s)) { col = GOLD; op = 0.35; }
    rec.mat.color.setHex(col);
    rec.mat.userData.baseColor = col;
    rec.mat.userData.target = op;
  });
}

function setEmphasis(mode) {
  emphasis = mode;
  const on = 0.85, off = 0.2;
  planeXY.mat.userData.target = mode === 'none' ? planeXY.base : (mode === 'xy' ? on : off);
  planeXZ.mat.userData.target = mode === 'none' ? planeXZ.base : (mode === 'xz' ? on : off);
  planeYZ.mat.userData.target = mode === 'none' ? planeYZ.base : (mode === 'yz' ? on : off);
  refreshOctantMats();
  const ids = { none: 'emNone', xy: 'emXY', xz: 'emXZ', yz: 'emYZ' };
  ['emNone', 'emXY', 'emXZ', 'emYZ'].forEach(i =>
    document.getElementById(i).classList.toggle('active', ids[mode] === i));
  const note = {
    none: 'Crossing one coordinate plane flips exactly one sign.',
    xy: 'z = 0 separates z &gt; 0 (warm) from z &lt; 0 (cool).',
    xz: 'y = 0 separates y &gt; 0 (warm) from y &lt; 0 (cool).',
    yz: 'x = 0 separates x &gt; 0 (warm) from x &lt; 0 (cool).'
  };
  document.getElementById('emNote').innerHTML = note[mode];
}

document.getElementById('emNone').onclick = () => setEmphasis('none');
document.getElementById('emXY').onclick = () => setEmphasis('xy');
document.getElementById('emXZ').onclick = () => setEmphasis('xz');
document.getElementById('emYZ').onclick = () => setEmphasis('yz');

/* ── hover a wedge ───────────────────────────────────────────────────────── */
const readout = document.getElementById('hoverRead');
function setHover(key) {
  if (key === hovered) return;
  if (hovered && octMap[hovered]) {
    const d = octMap[hovered].label.div;
    d.style.fontSize = '13px'; d.style.fontWeight = ''; d.style.color = '#141428';
  }
  hovered = key;
  if (hovered && octMap[hovered]) {
    const d = octMap[hovered].label.div;
    d.style.fontSize = '18px'; d.style.fontWeight = '700'; d.style.color = '#8a5d00';
    readout.innerHTML = octMap[hovered].def.t;
  } else {
    readout.innerHTML = '';
  }
  refreshOctantMats();
}

const _hRay = new THREE.Raycaster();
const _hPtr = new THREE.Vector2();
canvas.addEventListener('pointermove', (ev) => {
  const r = canvas.getBoundingClientRect();
  _hPtr.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  _hPtr.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  _hRay.setFromCamera(_hPtr, camera);
  const hits = _hRay.intersectObjects(octBoxes, false);
  setHover(hits.length ? hits[0].object.userData.key : null);
});
canvas.addEventListener('pointerleave', () => setHover(null));

/* ── guided demo ─────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'The three coordinate planes', em: 'none',
    n: 'Three mutually perpendicular translucent sheets meet at the origin: the teal xy-plane, the peach yz-plane, and the blue-violet xz-plane. Together they cut space into eight octants.' },
  { title: 'Above and below the xy-plane', em: 'xy',
    n: 'Emphasizing z = 0 splits space into the four octants with z &gt; 0 above and the four with z &lt; 0 below. Crossing this sheet changes only the third coordinate\u2019s sign.' },
  { title: 'Front and back of the xz-plane', em: 'xz',
    n: 'Now y = 0 is the dividing sheet: the half-space toward +y (right) and the half-space toward \u2212y recolor. Only the second coordinate\u2019s sign flips across it.' },
  { title: 'The two sides of the yz-plane', em: 'yz',
    n: 'With x = 0 emphasized, the wedges in front (x &gt; 0) separate from those behind (x &lt; 0). Octant I, labeled (+,+,+), is the near upper wedge on the positive side of all three planes.' }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setEmphasis(s.em);
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('stepNarr').innerHTML = s.n;
}
document.getElementById('stepPrev').onclick = () => { stopPlay(); goToStep(stepIdx - 1); };
document.getElementById('stepNext').onclick = () => { stopPlay(); goToStep(stepIdx + 1); };
let playTimer = null;
const playBtn = document.getElementById('stepPlay');
function stopPlay() { if (playTimer) { clearInterval(playTimer); playTimer = null; playBtn.classList.remove('active'); playBtn.textContent = 'Play'; } }
playBtn.onclick = () => {
  if (playTimer) { stopPlay(); return; }
  playBtn.classList.add('active'); playBtn.textContent = 'Pause';
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 3800);
};
goToStep(0);

/* ── opacity tweening ────────────────────────────────────────────────────── */
const tweened = [planeXY.mat, planeXZ.mat, planeYZ.mat, ...octBoxes.map(b => b.material)];
(function tweenLoop() {
  requestAnimationFrame(tweenLoop);
  for (const m of tweened) {
    const t = m.userData.target;
    if (Math.abs(m.opacity - t) > 0.002) m.opacity += (t - m.opacity) * 0.16;
    else m.opacity = t;
  }
})();
// @FIGURE_CODE_END

